fun EditableContentStore.apply(v: TechnicalFigure) = v.copy(
    title = text("figure", v.id, "title", v.title), labels = texts("figure", v.id, "labels", v.labels),
    caption = text("figure", v.id, "caption", v.caption), dimensionText = text("figure", v.id, "dimensionText", v.dimensionText),
    limits = text("figure", v.id, "limits", v.limits), sourceUrl = text("figure", v.id, "sourceUrl", v.sourceUrl)
)
